CREATE TABLE public.social_follower_history (platform text NOT NULL CHECK (platform IN ('instagram','tiktok')), day date NOT NULL, total_followers numeric, net_growth numeric, new_followers numeric, PRIMARY KEY(platform,day)); GRANT SELECT ON public.social_follower_history TO anon,authenticated; GRANT ALL ON public.social_follower_history TO service_role; ALTER TABLE public.social_follower_history ENABLE ROW LEVEL SECURITY; CREATE POLICY "Read manual follower history" ON public.social_follower_history FOR SELECT TO anon,authenticated USING (true);